    // copying backward so that we never overwrite characters we still
    // need to read.
    let end: usize = l - p;
    let mut i: usize = end;
    // Loop invariant:
    //   • at <= i <= end
    //   • positions [i .. end) have already been fixed up,
    //       i.e. line[j] == old(line)[j+p] for j in (i .. end)
    //   • positions [0 .. at) are always untouched
